write("crates/chess-search/tests/search_iterative_deepening.rs", "use chess_core::{Move, Position, SearchHistory};\nuse chess_search::{\n    alpha_beta_search, iterative_deepening_search,\n    iterative_deepening_search_with_transposition_table, AlphaBetaSearchError,\n    AspirationWindowOutcome, IterativeDeepeningSearchError, PrincipalVariationTermination,\n    TranspositionTable, TranspositionTableDiagnostics,\n    DEFAULT_ASPIRATION_HALF_WIDTH_CENTIPAWNS, MAX_MATE_PLY,\n};\n\nfn benchmark_position() -> Position {\n    \"7k/8/8/1p2q3/2P1Q3/8/K7/8 w - - 0 1\"\n        .parse()\n        .expect(\"iterative-deepening benchmark FEN is valid\")\n}\n\nfn assert_legal_line(root: &Position, line: &[Move]) {\n    let mut cursor = root.clone();\n    for current in line {\n        let tokens = cursor\n            .legal_move_tokens()\n            .expect(\"PV legal tokens generate\");\n        let token = tokens\n            .iter()\n            .find(|token| token.move_made() == *current)\n            .expect(\"every returned PV move is legal in sequence\");\n        cursor\n            .make_legal_token(token)\n            .expect(\"returned PV move applies\");\n    }\n}\n\n#[test]\nfn every_depth_is_preserved_and_matches_independent_full_window_search() {\n    let root = benchmark_position();\n    let mut position = root.clone();\n    let position_snapshot = position.clone();\n    let mut history = SearchHistory::from_position(&position);\n    let history_snapshot = history.clone();\n    let mut table = TranspositionTable::new(1).expect(\"bounded table allocates\");\n\n    let result = iterative_deepening_search_with_transposition_table(\n        &mut position,\n        &mut history,\n        3,\n        &mut table,\n    )\n    .expect(\"iterative deepening succeeds\");\n\n    assert_eq!(result.completed_depth(), 3);\n    assert_eq!(result.iterations().len(), 3);\n    assert_eq!(\n        result\n            .iterations()\n            .iter()\n            .map(|iteration| iteration.depth())\n            .collect::<Vec<_>>(),\n        vec![1, 2, 3]\n    );\n    assert_eq!(\n        result.total_nodes(),\n        result\n            .iterations()\n            .iter()\n            .map(|iteration| iteration.nodes())\n            .sum()\n    );\n\n    for (index, iteration) in result.iterations().iter().enumerate() {\n        let mut independent_position = benchmark_position();\n        let mut independent_history = SearchHistory::from_position(&independent_position);\n        let independent = alpha_beta_search(\n            &mut independent_position,\n            &mut independent_history,\n            iteration.depth(),\n        )\n        .expect(\"independent fixed-depth search succeeds\");\n\n        assert_eq!(iteration.score(), independent.score());\n        assert_eq!(iteration.best_move(), independent.best_move());\n        assert_eq!(\n            iteration.principal_variation().moves().first().copied(),\n            iteration.best_move()\n        );\n        assert!(iteration.principal_variation().len() <= usize::from(iteration.depth()));\n        assert_legal_line(&root, iteration.principal_variation().moves());\n\n        let aspiration = iteration.aspiration_diagnostics();\n        if index == 0 {\n            assert_eq!(aspiration.center(), None);\n            assert!(aspiration.initial_attempt().is_full_window());\n        } else {\n            let prior = result.iterations()[index - 1].score();\n            assert_eq!(aspiration.center(), Some(prior));\n            let initial = aspiration.initial_attempt();\n            if !initial.is_full_window() {\n                assert_eq!(\n                    initial.alpha().centipawns(),\n                    prior.centipawns() - DEFAULT_ASPIRATION_HALF_WIDTH_CENTIPAWNS\n                );\n                assert_eq!(\n                    initial.beta().centipawns(),\n                    prior.centipawns() + DEFAULT_ASPIRATION_HALF_WIDTH_CENTIPAWNS\n                );\n            }\n        }\n        assert_eq!(\n            aspiration.final_attempt().outcome(),\n            AspirationWindowOutcome::Exact\n        );\n        assert_eq!(\n            aspiration.final_attempt().exact_score(),\n            Some(iteration.score())\n        );\n        assert!(aspiration.retry_count() <= 1);\n\n        let initial = aspiration.initial_attempt();\n        let expected_nodes = aspiration.full_window_retry().map_or(initial.nodes(), |retry| {\n            initial\n                .nodes()\n                .checked_add(retry.nodes())\n                .expect(\"small iteration node total fits\")\n        });\n        let expected_diagnostics = aspiration.full_window_retry().map_or(\n            initial.transposition_diagnostics(),\n            |retry| {\n                initial\n                    .transposition_diagnostics()\n                    .saturating_add(retry.transposition_diagnostics())\n            },\n        );\n        assert_eq!(iteration.nodes(), expected_nodes);\n        assert_eq!(iteration.transposition_diagnostics(), expected_diagnostics);\n        assert!(iteration.result().nodes() <= iteration.nodes());\n\n        assert_eq!(independent_position, benchmark_position());\n        assert_eq!(\n            independent_position.zobrist(),\n            independent_position.recomputed_zobrist()\n        );\n    }\n\n    assert_eq!(\n        result\n            .iterations()\n            .iter()\n            .map(|iteration| iteration.transposition_generation())\n            .collect::<Vec<_>>(),\n        vec![1, 2, 3]\n    );\n    assert_eq!(table.generation(), 3);\n    assert!(result.iterations()[0].transposition_diagnostics().probes() > 0);\n    assert!(result.iterations()[1].transposition_diagnostics().hits() > 0);\n    assert!(result.iterations()[2].transposition_diagnostics().hits() > 0);\n    for iteration in result.iterations() {\n        assert!(iteration.transposition_diagnostics().stores() > 0);\n        assert!(iteration.hash_full().sampled_slots() > 0);\n        assert!(iteration.hash_full().per_mille() <= 1_000);\n    }\n\n    assert_eq!(position, position_snapshot);\n    assert_eq!(history, history_snapshot);\n    assert_eq!(position.zobrist(), position.recomputed_zobrist());\n}\n\n#[test]\nfn convenience_search_reuses_one_bounded_table_and_returns_the_final_iteration() {\n    let root = Position::starting();\n    let mut position = root.clone();\n    let position_snapshot = position.clone();\n    let mut history = SearchHistory::from_position(&position);\n    let history_snapshot = history.clone();\n\n    let result = iterative_deepening_search(&mut position, &mut history, 3)\n        .expect(\"convenience iterative deepening succeeds\");\n    let final_iteration = result\n        .final_iteration()\n        .expect(\"positive maximum depth always completes a final iteration\");\n\n    assert_eq!(final_iteration.depth(), 3);\n    assert_eq!(final_iteration.transposition_generation(), 3);\n    assert!(final_iteration.result().nodes() <= final_iteration.nodes());\n    assert!(final_iteration.transposition_diagnostics().hits() > 0);\n    assert_eq!(\n        final_iteration\n            .aspiration_diagnostics()\n            .final_attempt()\n            .outcome(),\n        AspirationWindowOutcome::Exact\n    );\n    assert!(!final_iteration.principal_variation().is_empty());\n    assert_eq!(\n        final_iteration.ponder_move(),\n        final_iteration\n            .principal_variation()\n            .moves()\n            .get(1)\n            .copied()\n    );\n    assert_eq!(result.ponder_move(), final_iteration.ponder_move());\n    assert_eq!(\n        result.principal_variation(),\n        Some(final_iteration.principal_variation())\n    );\n    assert_legal_line(&root, final_iteration.principal_variation().moves());\n    assert_eq!(position, position_snapshot);\n    assert_eq!(history, history_snapshot);\n    assert_eq!(position.zobrist(), position.recomputed_zobrist());\n}\n\n#[test]\nfn terminal_roots_use_safe_full_windows_and_empty_terminal_principal_variations() {\n    let mut position: Position = \"7k/6Q1/6K1/8/8/8/8/8 b - - 0 1\"\n        .parse()\n        .expect(\"checkmate FEN is valid\");\n    let position_snapshot = position.clone();\n    let mut history = SearchHistory::from_position(&position);\n    let history_snapshot = history.clone();\n    let mut table = TranspositionTable::new(1).expect(\"bounded table allocates\");\n\n    let result = iterative_deepening_search_with_transposition_table(\n        &mut position,\n        &mut history,\n        3,\n        &mut table,\n    )\n    .expect(\"terminal iterative deepening succeeds\");\n\n    assert_eq!(result.iterations().len(), 3);\n    for iteration in result.iterations() {\n        assert_eq!(iteration.nodes(), 1);\n        assert_eq!(iteration.best_move(), None);\n        assert!(iteration.score().is_mate());\n        assert!(iteration.principal_variation().is_empty());\n        assert_eq!(\n            iteration.principal_variation().termination(),\n            PrincipalVariationTermination::TerminalPosition { ply: 0 }\n        );\n        assert_eq!(iteration.ponder_move(), None);\n        assert!(iteration\n            .aspiration_diagnostics()\n            .initial_attempt()\n            .is_full_window());\n        assert_eq!(iteration.aspiration_diagnostics().retry_count(), 0);\n        assert_eq!(\n            iteration.transposition_diagnostics(),\n            TranspositionTableDiagnostics::default()\n        );\n        assert_eq!(iteration.hash_full().occupied_current_generation(), 0);\n    }\n    assert_eq!(result.total_nodes(), 3);\n    assert_eq!(table.generation(), 3);\n    assert_eq!(position, position_snapshot);\n    assert_eq!(history, history_snapshot);\n}\n\n#[test]\nfn invalid_maximum_depths_fail_before_mutating_a_caller_owned_table() {\n    let mut position = benchmark_position();\n    let mut history = SearchHistory::from_position(&position);\n    let mut table = TranspositionTable::new(1).expect(\"bounded table allocates\");\n    let generation = table.generation();\n    let diagnostics = table.diagnostics();\n    let capacity = table.entry_capacity();\n\n    assert_eq!(\n        iterative_deepening_search_with_transposition_table(\n            &mut position,\n            &mut history,\n            0,\n            &mut table,\n        ),\n        Err(IterativeDeepeningSearchError::ZeroMaximumDepth)\n    );\n    assert_eq!(\n        iterative_deepening_search_with_transposition_table(\n            &mut position,\n            &mut history,\n            MAX_MATE_PLY + 1,\n            &mut table,\n        ),\n        Err(IterativeDeepeningSearchError::MaximumDepthTooLarge {\n            maximum_depth: MAX_MATE_PLY + 1,\n            supported: MAX_MATE_PLY,\n        })\n    );\n\n    assert_eq!(table.generation(), generation);\n    assert_eq!(table.diagnostics(), diagnostics);\n    assert_eq!(table.entry_capacity(), capacity);\n}\n\n#[test]\nfn mismatched_history_fails_on_depth_one_without_mutating_table_or_position() {\n    let mut position = benchmark_position();\n    let position_snapshot = position.clone();\n    let other_position: Position = \"8/8/8/8/8/8/4K3/6k1 w - - 0 1\"\n        .parse()\n        .expect(\"alternate history root is valid\");\n    let mut history = SearchHistory::from_position(&other_position);\n    let history_snapshot = history.clone();\n    let mut table = TranspositionTable::new(1).expect(\"bounded table allocates\");\n\n    let error = iterative_deepening_search_with_transposition_table(\n        &mut position,\n        &mut history,\n        2,\n        &mut table,\n    )\n    .expect_err(\"mismatched history must fail\");\n\n    assert!(matches!(\n        error,\n        IterativeDeepeningSearchError::IterationFailed {\n            depth: 1,\n            error: AlphaBetaSearchError::HistoryPositionMismatch { .. },\n        }\n    ));\n    assert_eq!(table.generation(), 0);\n    assert_eq!(\n        table.diagnostics(),\n        TranspositionTableDiagnostics::default()\n    );\n    assert_eq!(position, position_snapshot);\n    assert_eq!(history, history_snapshot);\n    assert_eq!(position.zobrist(), position.recomputed_zobrist());\n}\n")
write("docs/RUST_ASPIRATION_WINDOWS.md", "# Rust Aspiration Windows — Task 16.2\n\nTask 16.2 adds bounded score-centered aspiration searches to iterative deepening without allowing a root bound to masquerade as an exact completed result.\n\n## Policy\n\nDepth one has no prior exact score and therefore searches the complete supported score domain.\n\nFor each later depth:\n\n1. take the exact score from the immediately preceding completed iteration;\n2. construct an initial window centered on that score with the default half-width `DEFAULT_ASPIRATION_HALF_WIDTH_CENTIPAWNS`, currently 50 centipawns;\n3. run one fail-soft root search;\n4. classify the result as exact, fail-low, or fail-high;\n5. on fail-low or fail-high, perform exactly one complete-window retry;\n6. retain only an exact attempt as the completed iteration result.\n\nA prior score too close to either absolute mate-score boundary uses the complete window immediately because a symmetric bounded window cannot be represented safely there.\n\n## Bound safety\n\n`AspirationWindowOutcome` is explicit:\n\n- `Exact` means the score lies strictly inside the requested bounded window, or the complete score domain was searched;\n- `FailLow` means the reported fail-soft score is an upper bound at or below alpha;\n- `FailHigh` means the reported fail-soft score is a lower bound at or above beta.\n\n`AspirationWindowAttempt::reported_score` always exposes the raw fail-soft result for diagnostics. `AspirationWindowAttempt::exact_score` returns `None` for fail-low and fail-high. The iterative-deepening layer cannot construct a completed iteration from those bound outcomes; it must recover through the complete-window retry.\n\nThe retry is typed and fail-loud. If a complete-window attempt were ever classified as a bound, the search returns `FullWindowDidNotResolveExactly` instead of publishing an inexact result.\n\n## Retry and table behavior\n\nEach completed depth advances the transposition-table generation exactly once. A retry remains in the same generation so entries found by the failed attempt are reusable without making one logical iteration appear to be multiple generations.\n\nDiagnostics reset before each attempt. Every `AspirationWindowAttempt` records:\n\n- alpha and beta;\n- outcome;\n- reported score and optional exact score;\n- nodes for that attempt;\n- TT probe/store counters;\n- bounded hash-full sample;\n- shared generation identifier.\n\n`AspirationWindowDiagnostics` stores one initial attempt and at most one full-window retry. `IterativeDeepeningIteration::nodes` is the checked sum of all attempts at that depth. `IterativeDeepeningIteration::transposition_diagnostics` is the saturating aggregate, while the exact per-attempt snapshots remain available.\n\n## Determinism and restoration\n\nThe exact completed score and canonical best move are compared against an independent full-window fixed-depth search. Failed aspiration attempts never become PV roots. Principal variation reconstruction occurs only after the exact attempt finishes and the root position and detached history have been restored.\n\nRegression coverage includes:\n\n- prior-score centering;\n- deterministic fail-low recovery;\n- deterministic fail-high recovery;\n- explicit proof that bounds have no exact score;\n- one-retry maximum;\n- exact score and best-move equivalence;\n- retry node and TT diagnostics;\n- one generation per depth;\n- legal PV reconstruction and ponder preservation;\n- terminal and mate-boundary full-window fallback;\n- exact position, history, and Zobrist restoration.\n\n## Deferred work\n\nTask 16.2 does not add node/time/infinite limits, last-completed-iteration cancellation recovery, the final unified Task 16.6 result API, or check extensions. Those remain Tasks 16.4 through 16.7.\n")
write("docs/RUST_ITERATIVE_DEEPENING.md", "# Rust Iterative Deepening — Tasks 16.1–16.3\n\nThe iterative-deepening layer performs complete searches at every depth from one through the requested maximum, preserves one exact completed record per depth, applies bounded aspiration windows after depth one, and reconstructs a legal principal variation only from exact search data.\n\n## Search sequence\n\nA request for maximum depth `N` searches depths `1..=N` in ascending order. No depth is skipped.\n\nDepth one uses the complete supported alpha-beta score domain. Each later depth begins with a bounded window centered on the prior completed exact score. An initial fail-low or fail-high triggers exactly one complete-window retry. A bound is never retained as the completed iteration.\n\nEvery `IterativeDeepeningIteration` contains:\n\n- completed depth;\n- exact `AlphaBetaSearchResult`;\n- exact score and deterministic best move;\n- safely reconstructed legal principal variation and optional ponder move;\n- nodes visited by all attempts at that depth;\n- bounded aspiration and retry diagnostics;\n- aggregate and per-attempt transposition-table diagnostics;\n- bounded current-generation hash-full estimate;\n- one generation identifier shared by all attempts at that depth.\n\n`IterativeDeepeningSearchResult::total_nodes` is the checked sum of all attempts at all completed depths.\n\nThe aspiration contract is documented in `docs/RUST_ASPIRATION_WINDOWS.md`. Principal-variation safety is documented in `docs/RUST_PRINCIPAL_VARIATION.md`.\n\n## Table and history reuse\n\nThe convenience entry point `iterative_deepening_search` allocates one fixed-capacity table using `DEFAULT_TRANSPOSITION_TABLE_MEBIBYTES`, currently 1 MiB.\n\n`iterative_deepening_search_with_transposition_table` accepts a caller-owned table. Entries remain available across depths and across an aspiration retry. The generation advances exactly once per depth. Diagnostic counters reset per attempt, then the returned iteration keeps both the exact attempt snapshots and a saturating aggregate.\n\nThe same root `Position` and detached `SearchHistory` are reused throughout. Every attempt must restore both before another attempt or depth begins. Invalid maximum depths fail before table mutation. A position/history mismatch fails at depth one before generation advancement.\n\n## Exactness and determinism\n\nOnly `AspirationWindowOutcome::Exact` can become an iteration result. A fail-low score is an upper bound; a fail-high score is a lower bound. `AspirationWindowAttempt::exact_score` returns `None` for both.\n\nComplete-window recovery preserves the fixed-depth full-window score and canonical best move. Root determinism, repetition-sensitive score suppression, mate normalization, complete-key TT verification, legal-root-move validation, and fixed-capacity behavior remain those established by Task 15.\n\nPV reconstruction runs only after exact recovery and validates every move in sequence.\n\n## Bounded result storage\n\nMaximum depth must be in `1..=MAX_MATE_PLY`. Result storage reserves exactly that many iteration records through a fallible allocation.\n\nEach depth has exactly one initial attempt and at most one retry. There is no unbounded widening loop. Zero depth, excessive depth, storage allocation failure, attempt failure, unexpected full-window bound classification, PV reconstruction failure, and node-total overflow are typed errors.\n\n## Deferred Task 16 work\n\nTasks 16.1, 16.2, and 16.3 do not yet add:\n\n- node, soft-time, hard-time, infinite, or explicit-stop limits;\n- cancellation fallback to the last fully completed iteration;\n- the final unified Task 16.6 search-result API;\n- check extensions.\n")

